import type { ColumnDef, SortingState, PaginationState, ColumnFiltersState } from '@tanstack/react-table';

export interface DataTableColumn {
    name: string;
    label: string;
    sortable: boolean;
    searchable: boolean;
    filterable: boolean;
    hidden: boolean;
    filter_type?: 'text' | 'select' | 'boolean' | null;
    filter_options?: Array<{ value: string; label: string }>;
}

export interface DataTableMeta {
    current_page: number;
    per_page: number;
    from: number | null;
    to: number | null;
    total: number;
    last_page: number;
}

export interface DataTableQuery {
    page: number;
    per_page: number;
    search: string;
    sort: Array<{ column: string; direction: string }>;
    searches: Array<{ column: string; value: string }>;
    filters: Array<{ column: string; value: unknown }>;
}

export interface DataTableConfig {
    debounce: number;
    per_page_options: number[];
}

export interface DataTableResponse<TData = unknown> {
    data: TData[];
    meta: DataTableMeta;
    query: DataTableQuery;
    columns: DataTableColumn[];
    config: DataTableConfig;
}

export interface DataTableState {
    page: number;
    perPage: number;
    search: string;
    sort: Array<{ column: string; direction: 'asc' | 'desc' }>;
    searches: Record<string, string>;
    filters: Record<string, unknown>;
}

export interface DataTableOptions<TData = unknown> {
    data: DataTableResponse<TData>;
    onDataChange?: (_data: DataTableResponse<TData>) => void;
    dataPropName?: string;
}

export type DataTableColumnDef<TData = unknown> = ColumnDef<TData, unknown>;

export type DataTableSortingState = SortingState;
export type DataTablePaginationState = PaginationState;
export type DataTableColumnFiltersState = ColumnFiltersState;

'use client';

import { type ReactNode, forwardRef } from 'react';
import { flexRender } from '@tanstack/react-table';
import { type DataTableResponse } from './types';
import {
    Table,
    TableHeader,
    TableBody,
    TableFooter,
    TableRow,
    TableCell,
} from '@/components/ui/table';
import { DataTableToolbar } from './data-table-toolbar';
import { DataTablePagination } from './data-table-pagination';
import { DataTableColumnHeader } from './data-table-column-header';
import { DataTableColumnVisibility } from './data-table-column-visibility';
import { DataTableEmpty } from './data-table-empty';
import { useDataTable } from './use-data-table';

interface DataTableProps<TData extends Record<string, unknown>> {
    data: DataTableResponse<TData>;
    children?: ReactNode;
    dataPropName?: string;
}

export const DataTable = forwardRef<HTMLTableElement, DataTableProps<Record<string, unknown>>>(
    ({ data, children, dataPropName = 'data', ...props }, ref) => {
        const {
            table,
            handlePageChange,
            handlePerPageChange,
            handleSearchChange,
            handleColumnSearchChange,
            handleFilterChange,
            state,
            perPageOptions,
            columnSearches,
        } = useDataTable<Record<string, unknown>>({ data, dataPropName });

        return (
            <div className="space-y-4">
                <DataTableToolbar
                    search={state.search}
                    onSearchChange={handleSearchChange}
                    perPage={state.perPage}
                    onPerPageChange={handlePerPageChange}
                    perPageOptions={perPageOptions}
                />
                <div className="rounded-md border">
                    <Table ref={ref} className="w-full caption-bottom text-sm" {...props}>
<TableHeader>
                {table.getHeaderGroups().map((headerGroup) => (
                    <TableRow key={headerGroup.id}>
                        {headerGroup.headers.map((header) => (
                            <DataTableColumnHeader
                                key={header.id}
                                header={header}
                                column={header.column}
                                onColumnSearchChange={handleColumnSearchChange}
                                onFilterChange={handleFilterChange}
                                columnSearchValue={columnSearches[header.column.id] ?? ''}
                                currentFilterValue={state.filters[header.column.id]}
                            />
                        ))}
                    </TableRow>
                ))}
            </TableHeader>
                        <TableBody>
                            {table.getRowModel().rows.length === 0 ? (
                                <DataTableEmpty columns={table.getAllLeafColumns().length} />
                            ) : (
                                table.getRowModel().rows.map((row) => (
                                    <TableRow key={row.id} className="border-b transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted">
                                        {row.getVisibleCells().map((cell) => (
                                            <TableCell key={cell.id} className="p-4 align-middle">
                                                {flexRender(cell.column.columnDef.cell!, cell.getContext())}
                                            </TableCell>
                                        ))}
                                    </TableRow>
                                ))
                            )}
                        </TableBody>
                        <TableFooter>
                            <DataTablePagination
                                currentPage={state.page}
                                perPage={state.perPage}
                                onPageChange={handlePageChange}
                                totalPages={data.meta.last_page}
                                totalItems={data.meta.total}
                            />
                        </TableFooter>
                    </Table>
                </div>
                <DataTableColumnVisibility table={table} />
                {children}
            </div>
        );
    }
);

DataTable.displayName = 'DataTable';

'use client';

import React from 'react';
import { type ReactNode } from 'react';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

interface DataTableToolbarProps {
    search: string;
    onSearchChange: (_value: string) => void;
    perPage: number;
    onPerPageChange: (_value: number) => void;
    perPageOptions: number[];
    children?: ReactNode;
}

export function DataTableToolbar({
    search,
    onSearchChange,
    perPage,
    onPerPageChange,
    perPageOptions,
    children,
}: DataTableToolbarProps) {
    return (
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div className="flex items-center gap-2">
                <Input
                    placeholder="Search..."
                    value={search}
                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => onSearchChange(e.target.value)}
                    className="w-64 max-w-[200px]"
                    aria-label="Global search"
                />
                {children}
            </div>
            <div className="flex items-center gap-2">
                <label htmlFor="per-page" className="text-sm text-muted-foreground">
                    Show
                </label>
                <Select value={String(perPage)} onValueChange={(value: string) => onPerPageChange(Number(value))}>
                    <SelectTrigger id="per-page" className="w-[100px]">
                        <SelectValue placeholder="Per page" />
                    </SelectTrigger>
                    <SelectContent>
                        {perPageOptions.map((option) => (
                            <SelectItem key={String(option)} value={String(option)}>
                                {option}
                            </SelectItem>
                        ))}
                    </SelectContent>
                </Select>
                <span className="text-sm text-muted-foreground">per page</span>
            </div>
        </div>
    );
}

'use client';

import { Button } from '@/components/ui/button';

interface DataTablePaginationProps {
    currentPage: number;
    perPage: number;
    onPageChange: (_page: number) => void;
    totalPages: number;
    totalItems: number;
}

export function DataTablePagination({
    currentPage,
    perPage,
    onPageChange,
    totalPages,
    totalItems,
}: DataTablePaginationProps) {
    const pageCount = totalPages;
    const from = (currentPage - 1) * perPage + 1;
    const to = Math.min(currentPage * perPage, totalItems);

    if (pageCount <= 1) {
        return (
            <div className="flex items-center justify-between border-t px-4 py-3 sm:px-6">
                <div className="text-sm text-muted-foreground">
                    Showing <span className="font-medium">{from}</span> to{' '}
                    <span className="font-medium">{to}</span> of{' '}
                    <span className="font-medium">{totalItems}</span> results
                </div>
            </div>
        );
    }

    const pages = getPageNumbers(currentPage, pageCount);

    return (
        <div className="flex items-center justify-between border-t px-4 py-3 sm:px-6">
            <div className="text-sm text-muted-foreground">
                Showing <span className="font-medium">{from}</span> to{' '}
                <span className="font-medium">{to}</span> of{' '}
                <span className="font-medium">{totalItems}</span> results
            </div>
            <div className="flex items-center gap-1">
                <Button
                    variant="outline"
                    size="sm"
                    onClick={() => onPageChange(1)}
                    disabled={currentPage === 1}
                    aria-label="First page"
                >
                    <span className="sr-only">First</span>
                    ««
                </Button>
                <Button
                    variant="outline"
                    size="sm"
                    onClick={() => onPageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    aria-label="Previous page"
                >
                    <span className="sr-only">Previous</span>
                    «
                </Button>
                {pages.map((page, index) => (
                    <Button
                        key={index}
                        variant={page === currentPage ? 'default' : 'outline'}
                        size="sm"
                        onClick={() => onPageChange(page)}
                        aria-label={`Page ${page}`}
                        aria-current={page === currentPage ? 'page' : undefined}
                    >
                        {page}
                    </Button>
                ))}
                <Button
                    variant="outline"
                    size="sm"
                    onClick={() => onPageChange(currentPage + 1)}
                    disabled={currentPage === pageCount}
                    aria-label="Next page"
                >
                    <span className="sr-only">Next</span>
                    »
                </Button>
                <Button
                    variant="outline"
                    size="sm"
                    onClick={() => onPageChange(pageCount)}
                    disabled={currentPage === pageCount}
                    aria-label="Last page"
                >
                    <span className="sr-only">Last</span>
                    »»
                </Button>
            </div>
        </div>
    );
}

function getPageNumbers(currentPage: number, totalPages: number): number[] {
    const pages: number[] = [];
    const maxVisible = 5;
    let start = Math.max(1, currentPage - Math.floor(maxVisible / 2));
    let end = Math.min(totalPages, start + maxVisible - 1);

    if (end - start + 1 < maxVisible) {
        start = Math.max(1, end - maxVisible + 1);
        end = Math.min(totalPages, start + maxVisible - 1);
    }

    for (let i = start; i <= end; i++) {
        pages.push(i);
    }

    return pages;
}

'use client';

import React, { useState, useEffect } from 'react';
import { type Column, type Header, type ColumnMeta, flexRender } from '@tanstack/react-table';
import { Input } from '@/components/ui/input';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
    DropdownMenuSeparator,
    DropdownMenuLabel,
} from '@/components/ui/dropdown-menu';
import { Checkbox } from '@/components/ui/checkbox';

interface DataTableColumnMeta extends ColumnMeta<unknown, unknown> {
    searchable?: boolean;
    filterable?: boolean;
    filter_type?: 'text' | 'select' | 'boolean' | null;
    filter_options?: Array<{ value: string; label: string }>;
}

interface DataTableColumnHeaderProps<TData extends Record<string, unknown>> {
    header: Header<TData, unknown>;
    column: Column<TData, unknown>;
    onColumnSearchChange: (_column: string, _value: string) => void;
    onFilterChange: (_column: string, _value: unknown) => void;
    columnSearchValue: string;
    currentFilterValue?: unknown;
}

export function DataTableColumnHeader<TData extends Record<string, unknown>>({
    header,
    column,
    onColumnSearchChange,
    onFilterChange,
    columnSearchValue,
    currentFilterValue,
}: DataTableColumnHeaderProps<TData>) {
    const canSort = column.columnDef.enableSorting;
    const meta = column.columnDef.meta as DataTableColumnMeta | undefined;
    const canSearch = meta?.searchable === true;
    const canFilter = meta?.filterable === true;
    const filterType = meta?.filter_type ?? 'text';
    const filterOptions = meta?.filter_options ?? [];
    const isFilterActive = currentFilterValue !== '' && currentFilterValue !== null && currentFilterValue !== undefined;

    const [filterInputValue, setFilterInputValue] = useState<string>('');

    useEffect(() => {
        if (filterType === 'text' && typeof currentFilterValue === 'string') {
            setFilterInputValue(currentFilterValue);
        } else if (filterType === 'text') {
            setFilterInputValue('');
        }
    }, [currentFilterValue, filterType]);

    const handleFilterSelect = (value: string) => {
        onFilterChange(column.id, value);
    };

    const handleFilterTextChange = (value: string) => {
        setFilterInputValue(value);
        onFilterChange(column.id, value);
    };

    const handleFilterBooleanChange = (value: boolean) => {
        onFilterChange(column.id, value);
    };

    const handleClearFilter = () => {
        setFilterInputValue('');
        onFilterChange(column.id, '');
    };

    return (
        <th className="relative px-4 py-3 text-left align-middle font-medium text-muted-foreground [&:has([role=checkbox])]:pr-0">
            <div className="flex items-center gap-2">
                {canSort && (
                    <button
                        onClick={() => column.toggleSorting(column.getIsSorted() === 'asc')}
                        className="flex items-center gap-1 hover:text-foreground transition-colors"
                        aria-label={`Sort by ${column.columnDef.header}`}
                    >
                        {flexRender(column.columnDef.header!, header.getContext())}
                        {column.getIsSorted() === 'asc' ? (
                            <span>↑</span>
                        ) : column.getIsSorted() === 'desc' ? (
                            <span>↓</span>
                        ) : (
                            <span className="text-muted-foreground">↕</span>
                        )}
                    </button>
                )}
                {!canSort && <span>{flexRender(column.columnDef.header!, header.getContext())}</span>}
            </div>
            <div className="absolute right-0 top-full mt-1 w-56 p-2 rounded-md border bg-popover shadow-lg hidden group-focus-within:block group-hover:block z-10">
                {canSearch && (
                    <div className="space-y-2">
                        <label className="block text-xs font-medium text-muted-foreground">
                            Column search
                        </label>
                        <Input
                            placeholder={`Search ${column.columnDef.header}...`}
                            onChange={(e: React.ChangeEvent<HTMLInputElement>) => onColumnSearchChange(column.id, e.target.value)}
                            value={columnSearchValue}
                        />
                    </div>
                )}
                {canFilter && (
                    <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                            <button className={`flex w-full items-center justify-between px-2 py-1 text-sm rounded ${isFilterActive ? 'text-foreground bg-primary/10' : 'text-muted-foreground hover:text-foreground'}`}>
                                Filter
                                <svg className="ml-2 h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
                                </svg>
                            </button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent className="w-64 p-2">
                            <DropdownMenuLabel className="text-xs font-medium text-muted-foreground">
                                Filter {column.columnDef.header as string}
                            </DropdownMenuLabel>
                            <DropdownMenuSeparator />
                            {filterType === 'select' && filterOptions.length > 0 && (
                                <div className="space-y-1">
                                    {filterOptions.map((option) => (
                                        <DropdownMenuItem
                                            key={option.value}
                                            onSelect={(e) => {
                                                e.preventDefault();
                                                handleFilterSelect(option.value);
                                            }}
                                            className={`flex items-center gap-2 px-2 py-1.5 text-sm ${currentFilterValue === option.value ? 'bg-primary/10 text-primary' : ''}`}
                                        >
                                            <Checkbox
                                                checked={currentFilterValue === option.value}
                                                onCheckedChange={() => handleFilterSelect(option.value)}
                                                className="h-4 w-4"
                                            />
                                            <span className="truncate">{option.label}</span>
                                        </DropdownMenuItem>
                                    ))}
                                </div>
                            )}
                            {filterType === 'boolean' && (
                                <div className="space-y-1">
                                    <DropdownMenuItem
                                        onSelect={(e) => {
                                            e.preventDefault();
                                            handleFilterBooleanChange(true);
                                        }}
                                        className={`flex items-center gap-2 px-2 py-1.5 text-sm ${currentFilterValue === true ? 'bg-primary/10 text-primary' : ''}`}
                                    >
                                        <Checkbox
                                            checked={currentFilterValue === true}
                                            onCheckedChange={() => handleFilterBooleanChange(true)}
                                            className="h-4 w-4"
                                        />
                                        <span className="truncate">Yes</span>
                                    </DropdownMenuItem>
                                    <DropdownMenuItem
                                        onSelect={(e) => {
                                            e.preventDefault();
                                            handleFilterBooleanChange(false);
                                        }}
                                        className={`flex items-center gap-2 px-2 py-1.5 text-sm ${currentFilterValue === false ? 'bg-primary/10 text-primary' : ''}`}
                                    >
                                        <Checkbox
                                            checked={currentFilterValue === false}
                                            onCheckedChange={() => handleFilterBooleanChange(false)}
                                            className="h-4 w-4"
                                        />
                                        <span className="truncate">No</span>
                                    </DropdownMenuItem>
                                </div>
                            )}
                            {filterType === 'text' && (
                                <div className="space-y-2">
                                    <Input
                                        placeholder={`Filter ${column.columnDef.header}...`}
                                        value={filterInputValue}
                                        onChange={(e: React.ChangeEvent<HTMLInputElement>) => handleFilterTextChange(e.target.value)}
                                        className="w-full"
                                    />
                                </div>
                            )}
                            {isFilterActive && (
                                <>
                                    <DropdownMenuSeparator />
                                    <DropdownMenuItem
                                        onClick={handleClearFilter}
                                        className="text-sm text-destructive"
                                    >
                                        Clear filter
                                    </DropdownMenuItem>
                                </>
                            )}
                        </DropdownMenuContent>
                    </DropdownMenu>
                )}
            </div>
        </th>
    );
}

'use client';

import React from 'react';
import { type Table, type Column } from '@tanstack/react-table';
import { Checkbox } from '@/components/ui/checkbox';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';

interface DataTableColumnVisibilityProps<TData extends Record<string, unknown>> {
    table: Table<TData>;
}

export function DataTableColumnVisibility<TData extends Record<string, unknown>>({
    table,
}: DataTableColumnVisibilityProps<TData>) {
    const columns = table.getAllLeafColumns();

    return (
        <DropdownMenu>
            <DropdownMenuTrigger asChild>
                <button className="flex items-center gap-2 rounded-md border bg-background px-3 py-2 text-sm hover:bg-accent">
                    <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                    </svg>
                    <span>Columns</span>
                </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent className="w-56 p-2" sideOffset={8} align="end">
                <div className="space-y-1">
                    {columns.map((column: Column<TData, unknown>) => (
                        <DropdownMenuItem
                            key={column.id}
                            className="flex items-center gap-2 px-2 py-1.5 text-sm"
                            onSelect={(e: React.MouseEvent<HTMLDivElement>) => e.preventDefault()}
                        >
                            <Checkbox
                                checked={column.getIsVisible()}
                                onCheckedChange={(checked: boolean) => column.toggleVisibility(checked)}
                                className="h-4 w-4"
                            />
                            <span className="truncate">{column.columnDef.header as string}</span>
                        </DropdownMenuItem>
                    ))}
                </div>
            </DropdownMenuContent>
        </DropdownMenu>
    );
}

'use client';

interface DataTableEmptyProps {
  columns: number;
}

export function DataTableEmpty({ columns }: DataTableEmptyProps) {
  return (
    <tr>
      <td colSpan={columns} className="py-12 text-center text-muted-foreground">
        No results found
      </td>
    </tr>
  );
}

'use client';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
    createColumnHelper,
    flexRender,
    createCoreRowModel,
    useTable,
    type SortingState,
    type PaginationState,
    type ColumnFiltersState,
    type ColumnDef,
    type FilterFnOption,
    type VisibilityState,
} from '@tanstack/react-table';
import { router } from '@inertiajs/react';
import type {
    DataTableState,
    DataTableOptions,
    DataTableColumn,
} from './types';

type ColumnSearchesState = Record<string, string>;

export function useDataTable<TData extends Record<string, unknown>>({
    data: initialData,
    dataPropName = 'data',
}: DataTableOptions<TData>) {
    const mountedRef = useRef(false);
    const debounceTimersRef = useRef<Record<string, ReturnType<typeof setTimeout>>>({});
    const sortingRef = useRef<SortingState>([]);

    const [state, setState] = useState<DataTableState>({
        page: initialData.query.page,
        perPage: initialData.query.per_page,
        search: initialData.query.search,
        sort: initialData.query.sort.map((s) => ({
            column: s.column,
            direction: s.direction as 'asc' | 'desc',
        })),
        searches: Object.fromEntries(
            initialData.query.searches.map((s) => [s.column, s.value])
        ),
        filters: Object.fromEntries(
            initialData.query.filters.map((f) => [f.column, f.value])
        ),
    });

    const debounceMs = initialData.config?.debounce ?? 300;
    const perPageOptions = initialData.config?.per_page_options ?? [10, 25, 50, 100];

    const initialColumnVisibility = useMemo<Record<string, boolean>>(() => {
        const visibility: Record<string, boolean> = {};
        initialData.columns.forEach((col) => {
            visibility[col.name] = !col.hidden;
        });
        return visibility;
    }, [initialData.columns]);

    const columnHelper = useMemo(() => createColumnHelper<TData>(), []);

    const columns = useMemo<ColumnDef<TData, unknown>[]>(() => {
        return initialData.columns.map((col: DataTableColumn) => {
            const column = columnHelper.accessor(
                (row: TData) => row[col.name as keyof TData] as unknown,
                {
                    header: col.label,
                    id: col.name,
                    cell: (info) => flexRender(info.column.columnDef.cell!, info),
                }
            );

            if (col.sortable) {
                column.enableSorting = true;
            }

            if (col.searchable) {
                column.meta = {
                    ...column.meta,
                    searchable: true,
                };
            }

            if (col.filterable) {
                column.meta = {
                    ...column.meta,
                    filterable: true,
                    filter_type: col.filter_type,
                    filter_options: col.filter_options,
                };
                column.filterFn = 'includes' as FilterFnOption<TData>;
            }

            return column;
        });
    }, [initialData.columns, columnHelper]);

    const [sorting, setSorting] = useState<SortingState>(
        state.sort.map((s) => ({ id: s.column, desc: s.direction === 'desc' }))
    );

    const [pagination, setPagination] = useState<PaginationState>({
        pageIndex: state.page - 1,
        pageSize: state.perPage,
    });

    const [globalFilter, setGlobalFilter] = useState<string>(state.search);

    const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>(
        Object.entries(state.filters).map(([key, value]) => ({ id: key, value })) as ColumnFiltersState
    );

    const [columnSearches, setColumnSearches] = useState<ColumnSearchesState>(state.searches);

    const [columnVisibility, setColumnVisibility] = useState<VisibilityState>(initialColumnVisibility);

    useEffect(() => {
        sortingRef.current = sorting;
    }, [sorting]);

    const visitWithParams = useCallback(
        (params: Record<string, unknown>) => {
            const currentParams = new URLSearchParams(window.location.search);
            Object.entries(params).forEach(([key, value]) => {
                if (value === '' || value === null || value === undefined) {
                    currentParams.delete(key);
                } else {
                    currentParams.set(key, String(value));
                }
            });
            router.visit(window.location.pathname + '?' + currentParams.toString(), {
                preserveScroll: true,
                preserveState: true,
                only: [dataPropName],
            });
        },
        [dataPropName]
    );

    const debouncedVisit = useCallback(
        (key: string, params: Record<string, unknown>) => {
            if (debounceTimersRef.current[key]) {
                clearTimeout(debounceTimersRef.current[key]);
            }
            debounceTimersRef.current[key] = setTimeout(() => {
                visitWithParams(params);
                delete debounceTimersRef.current[key];
            }, debounceMs);
        },
        [visitWithParams, debounceMs]
    );

    const handleSortChange = useCallback(
        (updater: SortingState | ((_old: SortingState) => SortingState)) => {
            const newSorting = typeof updater === 'function' ? updater(sortingRef.current) : updater;
            setSorting(newSorting);
            const sortString = newSorting
                .map((s) => (s.desc ? `-${s.id}` : s.id))
                .join(',');
            setState((prev) => ({
                ...prev,
                sort: newSorting.map((s) => ({ column: s.id, direction: s.desc ? 'desc' : 'asc' })),
            }));
            visitWithParams({ sort: sortString });
        },
        [visitWithParams]
    );

    const handlePageChange = useCallback(
        (pageIndex: number) => {
            const page = pageIndex + 1;
            setState((prev) => ({ ...prev, page }));
            setPagination((prev) => ({ ...prev, pageIndex }));
            visitWithParams({ page });
        },
        [visitWithParams]
    );

    const handlePerPageChange = useCallback(
        (pageSize: number) => {
            setState((prev) => ({ ...prev, perPage: pageSize, page: 1 }));
            setPagination((prev) => ({ ...prev, pageSize, pageIndex: 0 }));
            visitWithParams({ per_page: pageSize, page: 1 });
        },
        [visitWithParams]
    );

    const handleSearchChange = useCallback(
        (value: string) => {
            setGlobalFilter(value);
            setState((prev) => ({ ...prev, search: value, page: 1 }));
            setPagination((prev) => ({ ...prev, pageIndex: 0 }));
            debouncedVisit('search', { search: value, page: 1 });
        },
        [debouncedVisit]
    );

    const handleColumnSearchChange = useCallback(
        (column: string, value: string) => {
            setColumnSearches((prev) => {
                const next = { ...prev };
                if (value) {
                    next[column] = value;
                } else {
                    delete next[column];
                }
                return next;
            });
            setState((prev) => ({
                ...prev,
                searches: { ...prev.searches, [column]: value },
                page: 1,
            }));
            setPagination((prev) => ({ ...prev, pageIndex: 0 }));
            debouncedVisit(`searches.${column}`, { [`searches[${column}]`]: value || undefined, page: 1 });
        },
        [debouncedVisit]
    );

    const handleFilterChange = useCallback(
        (column: string, value: unknown) => {
            setColumnFilters((prev) => {
                const newFilters = new Map(prev.map((f) => [f.id, f.value]));
                if (value === '' || value === null || value === undefined) {
                    newFilters.delete(column);
                } else {
                    newFilters.set(column, value);
                }
                return Array.from(newFilters.entries()).map(([id, value]) => ({ id, value })) as ColumnFiltersState;
            });
            setState((prev) => ({
                ...prev,
                filters: { ...prev.filters, [column]: value },
                page: 1,
            }));
            setPagination((prev) => ({ ...prev, pageIndex: 0 }));
            const paramValue = value === '' || value === null || value === undefined ? undefined : value;
            visitWithParams({ [`filters[${column}]`]: paramValue, page: 1 });
        },
        [visitWithParams]
    );

    const handleColumnVisibilityChange = useCallback(
        (updater: VisibilityState | ((_old: VisibilityState) => VisibilityState)) => {
            const newVisibility = typeof updater === 'function' ? updater(columnVisibility) : updater;
            setColumnVisibility(newVisibility);
        },
        [columnVisibility]
    );

    useEffect(() => {
        setState({
            page: initialData.query.page,
            perPage: initialData.query.per_page,
            search: initialData.query.search,
            sort: initialData.query.sort.map((s) => ({
                column: s.column,
                direction: s.direction as 'asc' | 'desc',
            })),
            searches: Object.fromEntries(
                initialData.query.searches.map((s) => [s.column, s.value])
            ),
            filters: Object.fromEntries(
                initialData.query.filters.map((f) => [f.column, f.value])
            ),
        });
        setSorting(
            initialData.query.sort.map((s) => ({
                id: s.column,
                desc: s.direction === 'desc',
            }))
        );
        setPagination({
            pageIndex: initialData.query.page - 1,
            pageSize: initialData.query.per_page,
        });
        setGlobalFilter(initialData.query.search);
        setColumnFilters(
            Object.entries(
                Object.fromEntries(initialData.query.filters.map((f) => [f.column, f.value]))
            ).map(([id, value]) => ({ id, value })) as ColumnFiltersState
        );
        setColumnSearches(
            Object.fromEntries(initialData.query.searches.map((s) => [s.column, s.value]))
        );
    }, [initialData.query]);

    useEffect(() => {
        return () => {
            Object.values(debounceTimersRef.current).forEach((timer) => clearTimeout(timer));
            debounceTimersRef.current = {};
        };
    }, []);

    if (!mountedRef.current) {
        mountedRef.current = true;
    }

    const table = useTable({
        data: initialData.data as TData[],
        columns,
        state: {
            sorting,
            pagination,
            globalFilter,
            columnFilters,
            columnVisibility,
        },
        onSortingChange: handleSortChange,
        onPaginationChange: setPagination,
        onGlobalFilterChange: setGlobalFilter,
        onColumnFiltersChange: setColumnFilters,
        onColumnVisibilityChange: handleColumnVisibilityChange,
        getCoreRowModel: createCoreRowModel(),
        manualPagination: true,
        manualSorting: true,
        manualFiltering: true,
        pageCount: initialData.meta.last_page,
    });

    return {
        table,
        state,
        setState,
        handlePageChange,
        handlePerPageChange,
        handleSortChange,
        handleSearchChange,
        handleColumnSearchChange,
        handleFilterChange,
        perPageOptions,
        columnSearches,
    };
}

import { forwardRef } from 'react';
import type { TableHTMLAttributes, HTMLAttributes } from 'react';
export const Table = forwardRef<HTMLTableElement, TableHTMLAttributes<HTMLTableElement>>(({ children, ...props }, ref) => <table ref={ref} {...props}>{children}</table>);
export const TableHeader = ({ children, ...props }: HTMLAttributes<HTMLTableSectionElement>) => <thead {...props}>{children}</thead>;
export const TableBody = ({ children, ...props }: HTMLAttributes<HTMLTableSectionElement>) => <tbody {...props}>{children}</tbody>;
export const TableFooter = ({ children, ...props }: HTMLAttributes<HTMLTableSectionElement>) => <tfoot {...props}>{children}</tfoot>;
export const TableHead = ({ children, ...props }: HTMLAttributes<HTMLTableRowElement>) => <tr {...props}>{children}</tr>;
export const TableRow = ({ children, ...props }: HTMLAttributes<HTMLTableRowElement>) => <tr {...props}>{children}</tr>;
export const TableCell = ({ children, ...props }: HTMLAttributes<HTMLTableCellElement>) => <td {...props}>{children}</td>;
export const TableCaption = ({ children, ...props }: HTMLAttributes<HTMLTableCaptionElement>) => <caption {...props}>{children}</caption>;
